import React from 'react';
import { Box, Container } from '@mui/material';
import Slider from 'react-slick';
import 'slick-carousel/slick/slick.css';
import 'slick-carousel/slick/slick-theme.css';
import carouselBg from '../assets/Carousel.png';

const EventsSlider = () => {
  const slides = [
    {
      id: 1,
      image: '/path/to/image1.jpg',
      alt: 'Event 1',
      link: '#'
    },
    {
      id: 2,
      image: '/path/to/image2.jpg',
      alt: 'Event 2',
      link: '#'
    },
    // Daha fazla slide eklenebilir
  ];

  const settings = {
    dots: true,
    infinite: true,
    speed: 500,
    slidesToShow: 3,
    slidesToScroll: 1,
    autoplay: true,
    autoplaySpeed: 3000,
    responsive: [
      {
        breakpoint: 1024,
        settings: {
          slidesToShow: 2,
        }
      },
      {
        breakpoint: 600,
        settings: {
          slidesToShow: 1,
        }
      }
    ]
  };

  return (
    <Box
      sx={{
        backgroundImage: `url(${carouselBg})`,
        backgroundSize: 'cover',
        backgroundPosition: 'center',
        backgroundRepeat: 'no-repeat',
        py: 6,
        minHeight: '500px',
      }}
    >
      <Container maxWidth="lg">
        <Slider {...settings}>
          {slides.map((slide) => (
            <Box
              key={slide.id}
              sx={{
                px: 2,
              }}
            >
              <Box
                component="a"
                href={slide.link}
                sx={{
                  display: 'block',
                  backgroundColor: '#fff',
                  borderRadius: 2,
                  p: 2,
                  '&:hover': {
                    transform: 'translateY(-5px)',
                    transition: 'transform 0.3s ease',
                  },
                }}
              >
                <img
                  src={slide.image}
                  alt={slide.alt}
                  style={{
                    width: '100%',
                    height: 'auto',
                    borderRadius: '8px',
                    objectFit: 'cover',
                    aspectRatio: '16/9',
                  }}
                />
              </Box>
            </Box>
          ))}
        </Slider>
      </Container>
    </Box>
  );
};

export default EventsSlider;
